const item = $input.first().json.body || $input.first().json;
const prompt = "You are an autonomous AI specialist for Mana Community Platform operations: Community banquet, pooja, and party catering portion optimizer. Calculates per-head dietary requirements, vegetarian vs non-vegetarian distribution, buffer margins, and food waste minimization plan.

Analyze the following input payload securely:
__DATA__

Respond strictly with valid JSON conforming to this schema:
{"eventTitle":"Community Diwali Celebration Feast","totalGuests":120,"dietarySplit":{"vegCount":85,"nonVegCount":35,"jainCount":10},"optimizedPortions":[{"item":"Paneer Butter Masala","totalKg":22.5,"perHeadGrams":180},{"item":"Chicken Biryani","totalKg":14,"perHeadGrams":350},{"item":"Jeera Rice & Dal Tadka","totalKg":26,"perHeadGrams":220},{"item":"Gulab Jamun (2 pcs)","totalPcs":250,"perHeadPcs":2}],"recommendedBufferPercentage":8,"estimatedCostPerHead":380,"totalEstimatedBudget":45600,"foodWasteMitigationTips":"Set up live counter for rotis to eliminate leftover bread wastage; partner with Robin Hood Army for surplus donation by 22:30."}

Rules:
- Return pure JSON only, no markdown wrapping, no extra keys.
- Never expose PII or confidential tenant data.
- Ensure realistic domain heuristics.";
return [{ json: { prompt: prompt.replace("__DATA__", JSON.stringify(item, null, 2)), originalInput: item } }];

const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"eventTitle":"Community Diwali Celebration Feast","totalGuests":120,"dietarySplit":{"vegCount":85,"nonVegCount":35,"jainCount":10},"optimizedPortions":[{"item":"Paneer Butter Masala","totalKg":22.5,"perHeadGrams":180},{"item":"Chicken Biryani","totalKg":14,"perHeadGrams":350},{"item":"Jeera Rice & Dal Tadka","totalKg":26,"perHeadGrams":220},{"item":"Gulab Jamun (2 pcs)","totalPcs":250,"perHeadPcs":2}],"recommendedBufferPercentage":8,"estimatedCostPerHead":380,"totalEstimatedBudget":45600,"foodWasteMitigationTips":"Set up live counter for rotis to eliminate leftover bread wastage; partner with Robin Hood Army for surplus donation by 22:30."} } }];
}
